/** URL vignette i.ytimg.com pour une vidéo (réel, depuis YouTube) */
export function thumbFor(id: string): string {
  return `https://i.ytimg.com/vi/${id}/hqdefault.jpg`;
}

/** Miniature haute résolution (maxres si dispo, sinon hqdefault) */
export function thumbLargeFor(id: string): string {
  return `https://i.ytimg.com/vi/${id}/maxresdefault.jpg`;
}
